Technical Architecture# This document provides a technical deep-dive into dhamps-vdb&rsquo;s architecture for developers who want to understand or modify the codebase.
Project Structure# dhamps-vdb/ ├── main.go # Application entry point ├── go.mod # Go module definition ├── go.sum # Dependency checksums ├── sqlc.yaml # sqlc configuration ├── template.env # Environment template ├── .env # Local config (gitignored) │ ├── api/ │ └── openapi.yml # OpenAPI spec (not actively maintained) │ ├── internal/ # Internal packages (non-importable) │ ├── auth/ # Authentication logic │ │ └── authenticate.go # Bearer token validation │ │ │ ├── crypto/ # Encryption utilities │ │ └── crypto.go # AES-256-GCM encryption │ │ │ ├── database/ # Database layer │ │ ├── database.go # Connection pool management │ │ ├── migrations.go # Migration runner │ │ ├── db.go # Generated by sqlc │ │ ├── models.go # Generated by sqlc │ │ ├── queries.sql.go # Generated by sqlc │ │ │ │ │ ├── migrations/ # SQL migrations │ │ │ ├── 001_create_initial_scheme.sql │ │ │ ├── 002_create_emb_index.sql │ │ │ ├── 003_add_public_read_flag.sql │ │ │ ├── 004_refactor_llm_services_architecture.sql │ │ │ ├── tern.conf.tpl # Template for tern │ │ │ └── tern.conf # Generated (gitignored) │ │ │ │ │ └── queries/ # SQL queries for sqlc │ │ └── queries.sql # All database queries │ │ │ ├── handlers/ # HTTP request handlers │ │ ├── handlers.go # Common handler utilities │ │ ├── users.go # User endpoints │ │ ├── projects.go # Project endpoints │ │ ├── llm_services.go # LLM service endpoints │ │ ├── api_standards.go # API standard endpoints │ │ ├── embeddings.go # Embedding endpoints │ │ ├── similars.go # Similarity search endpoints │ │ ├── admin.go # Admin endpoints │ │ │ │ │ └── *_test.go # Test files │ │ ├── users_test.go │ │ ├── projects_test.go │ │ ├── projects_sharing_test.go │ │ ├── embeddings_test.go │ │ ├── llm_services_test.go │ │ ├── editor_permissions_test.go │ │ └── handlers_test.go │ │ │ └── models/ # Data models and options │ ├── options.go # CLI/environment options │ ├── users.go # User models │ ├── projects.go # Project models │ ├── instances.go # LLM instance models (new) │ ├── api_standards.go # API standard models │ ├── embeddings.go # Embedding models │ ├── similars.go # Similarity search models │ └── admin.go # Admin operation models │ ├── testdata/ # Test fixtures │ ├── postgres/ # PostgreSQL test data │ │ ├── enable-vector.sql │ │ └── users.yml │ │ │ └── *.json # JSON test fixtures │ ├── valid_user.json │ ├── valid_embeddings.json │ ├── valid_api_standard_*.json │ └── valid_llm_service_*.json │ └── docs/ # Documentation ├── content/ # Hugo content └── *.md # Additional docsCode Organization# 1. Entry Point (main.go)# The application entry point handles:
func main() { // 1. Parse CLI options and environment variables cli := huma.NewCLI(func(hooks huma.Hooks, opts *models.Options) { // 2. Initialize database connection pool pool := database.InitDB(opts) defer pool.Close() // 3. Run database migrations database.RunMigrations(pool, opts) // 4. Create HTTP router and Huma API router := http.NewServeMux() api := humago.New(router, huma.DefaultConfig(&#34;dhamps-vdb&#34;, &#34;0.1.0&#34;)) // 5. Register all routes handlers.AddRoutes(pool, keyGen, api) // 6. Start HTTP server server := &amp;http.Server{ Addr: fmt.Sprintf(&#34;%s:%d&#34;, opts.Host, opts.Port), Handler: router, } server.ListenAndServe() }) cli.Run() }2. Handlers (internal/handlers/)# Handlers process HTTP requests using the Huma framework pattern:
// Example: Create User Handler func RegisterUsersRoutes(pool *pgxpool.Pool, keyGen RandomKeyGenerator, api huma.API) { // Define request/response types type CreateUserInput struct { Body models.CreateUserRequest } type CreateUserOutput struct { Body models.User } // Register operation with Huma huma.Register(api, huma.Operation{ OperationID: &#34;create-user&#34;, Method: http.MethodPost, Path: &#34;/v1/users&#34;, Summary: &#34;Create a new user&#34;, Description: &#34;Admin only. Creates user and returns API key.&#34;, Security: []map[string][]string{{&#34;bearer&#34;: {}}}, }, func(ctx context.Context, input *CreateUserInput) (*CreateUserOutput, error) { // 1. Get authenticated user from context authUser := auth.GetAuthenticatedUser(ctx) // 2. Check authorization (admin only) if !authUser.IsAdmin { return nil, huma.Error403Forbidden(&#34;admin access required&#34;) } // 3. Validate input if err := input.Body.Validate(); err != nil { return nil, huma.Error400BadRequest(&#34;invalid input&#34;, err) } // 4. Business logic user, apiKey, err := createUserWithKey(ctx, pool, keyGen, &amp;input.Body) if err != nil { return nil, handleDatabaseError(err) } // 5. Return response return &amp;CreateUserOutput{Body: *user}, nil }) }Handler file organization:
handlers.go - Common utilities (context keys, error handling) users.go - User CRUD operations projects.go - Project CRUD and sharing llm_services.go - LLM service/instance management embeddings.go - Embedding CRUD operations similars.go - Similarity search admin.go - Administrative operations 3. Models (internal/models/)# Models define request/response structures:
// User model type User struct { UserHandle string `json:&#34;user_handle&#34; example:&#34;alice&#34;` Name string `json:&#34;name&#34; example:&#34;Alice Smith&#34;` Email string `json:&#34;email&#34; example:&#34;alice@example.com&#34;` CreatedAt time.Time `json:&#34;created_at&#34;` UpdatedAt time.Time `json:&#34;updated_at&#34;` } // Request model with validation type CreateUserRequest struct { UserHandle string `json:&#34;user_handle&#34; minLength:&#34;1&#34; maxLength:&#34;50&#34; pattern:&#34;^[a-z0-9_-]+$&#34;` Name string `json:&#34;name&#34; minLength:&#34;1&#34; maxLength:&#34;100&#34;` Email string `json:&#34;email&#34; format:&#34;email&#34;` } func (r *CreateUserRequest) Validate() error { if r.UserHandle == &#34;&#34; { return fmt.Errorf(&#34;user_handle is required&#34;) } if r.UserHandle == &#34;_system&#34; { return fmt.Errorf(&#34;_system is a reserved handle&#34;) } return nil }Model conventions:
Request models: Create*Request, Update*Request Response models: *Response, *Output Database models: Match database schema (generated by sqlc) 4. Database Layer (internal/database/)# Connection Management (database.go)# func InitDB(opts *models.Options) *pgxpool.Pool { connString := fmt.Sprintf( &#34;postgres://%s:%s@%s:%d/%s&#34;, opts.DBUser, opts.DBPassword, opts.DBHost, opts.DBPort, opts.DBName, ) config, err := pgxpool.ParseConfig(connString) if err != nil { log.Fatal(err) } // Configure connection pool config.MaxConns = 20 config.MinConns = 5 config.MaxConnIdleTime = time.Minute * 5 pool, err := pgxpool.NewWithConfig(context.Background(), config) if err != nil { log.Fatal(err) } return pool }Migrations (migrations.go)# Uses tern for versioned migrations:
func RunMigrations(pool *pgxpool.Pool, opts *models.Options) error { // Create tern configuration config := createTernConfig(opts) // Initialize migrator migrator, err := migrate.NewMigrator(context.Background(), pool, &#34;schema_version&#34;) if err != nil { return err } // Run pending migrations err = migrator.Migrate(context.Background()) if err != nil { return fmt.Errorf(&#34;migration failed: %w&#34;, err) } return nil }Migration files are numbered sequentially:
-- 001_create_initial_scheme.sql CREATE TABLE users ( user_id SERIAL PRIMARY KEY, user_handle TEXT UNIQUE NOT NULL, vdb_key TEXT UNIQUE NOT NULL, ... ); CREATE TABLE projects ( project_id SERIAL PRIMARY KEY, project_handle TEXT NOT NULL, owner TEXT NOT NULL REFERENCES users(user_handle), ... ); -- 002_create_emb_index.sql CREATE INDEX embedding_vector_idx ON embeddings USING hnsw (vector vector_cosine_ops);SQLC Queries (queries/queries.sql)# Write SQL, generate type-safe Go code:
-- name: UpsertUser :one INSERT INTO users ( user_handle, name, email, vdb_key, created_at, updated_at ) VALUES ( $1, $2, $3, $4, NOW(), NOW() ) ON CONFLICT (user_handle) DO UPDATE SET name = EXCLUDED.name, email = EXCLUDED.email, updated_at = NOW() RETURNING *; -- name: GetUserByHandle :one SELECT * FROM users WHERE user_handle = $1; -- name: GetAllUsers :many SELECT user_handle, name, email, created_at, updated_at FROM users ORDER BY user_handle ASC; -- name: DeleteUser :exec DELETE FROM users WHERE user_handle = $1;Generated Go code (queries.sql.go):
// Generated by sqlc func (q *Queries) UpsertUser(ctx context.Context, arg UpsertUserParams) (User, error) { row := q.db.QueryRow(ctx, upsertUser, arg.UserHandle, arg.Name, arg.Email, arg.VdbKey, ) var i User err := row.Scan( &amp;i.UserID, &amp;i.UserHandle, &amp;i.Name, &amp;i.Email, &amp;i.VdbKey, &amp;i.CreatedAt, &amp;i.UpdatedAt, ) return i, err }sqlc configuration (sqlc.yaml):
version: &#34;2&#34; sql: - engine: &#34;postgresql&#34; queries: &#34;internal/database/queries/queries.sql&#34; schema: &#34;internal/database/migrations/&#34; gen: go: package: &#34;database&#34; out: &#34;internal/database&#34; emit_json_tags: true emit_db_tags: true emit_prepared_queries: false emit_interface: falseRegenerate code after query changes:
sqlc generate --no-remote5. Authentication (internal/auth/)# Token-based authentication using Bearer tokens:
// Middleware checks Authorization header func AuthMiddleware(pool *pgxpool.Pool, adminKey string) func(http.Handler) http.Handler { return func(next http.Handler) http.Handler { return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { // Extract Bearer token authHeader := r.Header.Get(&#34;Authorization&#34;) token := strings.TrimPrefix(authHeader, &#34;Bearer &#34;) if token == &#34;&#34; { // Allow public access for certain endpoints ctx := context.WithValue(r.Context(), &#34;user&#34;, nil) next.ServeHTTP(w, r.WithContext(ctx)) return } // Check admin key if token == adminKey { user := &amp;AuthUser{Handle: &#34;_admin&#34;, IsAdmin: true} ctx := context.WithValue(r.Context(), &#34;user&#34;, user) next.ServeHTTP(w, r.WithContext(ctx)) return } // Look up user by API key hash hash := hashAPIKey(token) user, err := db.GetUserByKeyHash(r.Context(), pool, hash) if err != nil { http.Error(w, &#34;Unauthorized&#34;, http.StatusUnauthorized) return } authUser := &amp;AuthUser{Handle: user.UserHandle, IsAdmin: false} ctx := context.WithValue(r.Context(), &#34;user&#34;, authUser) next.ServeHTTP(w, r.WithContext(ctx)) }) } } // Helper to get authenticated user from context func GetAuthenticatedUser(ctx context.Context) *AuthUser { user, _ := ctx.Value(&#34;user&#34;).(*AuthUser) return user }6. Encryption (internal/crypto/)# AES-256-GCM encryption for sensitive data (API keys):
// Encrypt data with AES-256-GCM func Encrypt(plaintext []byte, key []byte) ([]byte, error) { // Ensure key is 32 bytes keyHash := sha256.Sum256(key) // Create AES cipher block, err := aes.NewCipher(keyHash[:]) if err != nil { return nil, err } // Create GCM gcm, err := cipher.NewGCM(block) if err != nil { return nil, err } // Generate random nonce nonce := make([]byte, gcm.NonceSize()) if _, err := io.ReadFull(rand.Reader, nonce); err != nil { return nil, err } // Encrypt and append nonce ciphertext := gcm.Seal(nonce, nonce, plaintext, nil) return ciphertext, nil } func Decrypt(ciphertext []byte, key []byte) ([]byte, error) { // Derive key keyHash := sha256.Sum256(key) block, err := aes.NewCipher(keyHash[:]) if err != nil { return nil, err } gcm, err := cipher.NewGCM(block) if err != nil { return nil, err } // Extract nonce nonceSize := gcm.NonceSize() nonce, ciphertext := ciphertext[:nonceSize], ciphertext[nonceSize:] // Decrypt plaintext, err := gcm.Open(nil, nonce, ciphertext, nil) if err != nil { return nil, err } return plaintext, nil }Huma Framework Integration# dhamps-vdb uses Huma for API development:
Benefits# Automatic OpenAPI generation - No manual spec maintenance Request/response validation - Type-safe with JSON schema Error handling - Standardized error responses Documentation - Interactive docs at /docs Operation Registration Pattern# huma.Register(api, huma.Operation{ OperationID: &#34;get-project&#34;, Method: http.MethodGet, Path: &#34;/v1/projects/{owner}/{project}&#34;, Summary: &#34;Get project details&#34;, Description: &#34;Returns full project information including metadata schema&#34;, Tags: []string{&#34;Projects&#34;}, Security: []map[string][]string{{&#34;bearer&#34;: {}}}, MaxBodyBytes: 1024, // Limit request size DefaultStatus: http.StatusOK, Errors: []int{400, 401, 403, 404, 500}, }, handlerFunction)Input/Output Patterns# // Path parameters, query parameters, and body type GetSimilarInput struct { Owner string `path:&#34;owner&#34; doc:&#34;Project owner&#34;` Project string `path:&#34;project&#34; doc:&#34;Project handle&#34;` TextID string `path:&#34;text_id&#34; doc:&#34;Text identifier&#34;` Threshold float32 `query:&#34;threshold&#34; default:&#34;0.5&#34; doc:&#34;Similarity threshold&#34;` Limit int `query:&#34;limit&#34; default:&#34;10&#34; maximum:&#34;200&#34; doc:&#34;Max results&#34;` } // Response with status code type GetSimilarOutput struct { Status int Body models.SimilarResponse }Error Response Pattern# // Standard error responses return nil, huma.Error400BadRequest(&#34;validation failed&#34;, err) return nil, huma.Error401Unauthorized(&#34;invalid credentials&#34;) return nil, huma.Error403Forbidden(&#34;insufficient permissions&#34;) return nil, huma.Error404NotFound(&#34;project not found&#34;) return nil, huma.Error500InternalServerError(&#34;database error&#34;, err) // Custom error with details return nil, huma.NewError(400, &#34;Dimension Mismatch&#34;, fmt.Sprintf(&#34;expected %d dimensions, got %d&#34;, expected, actual))Design Patterns# 1. Repository Pattern (via sqlc)# Database access is centralized in generated queries:
// Don&#39;t write SQL in handlers // Bad: rows, err := pool.Query(ctx, &#34;SELECT * FROM users&#34;) // Good: Use generated functions users, err := db.GetAllUsers(ctx)2. Dependency Injection# Pass dependencies explicitly:
// Inject pool into handlers func RegisterUsersRoutes(pool *pgxpool.Pool, keyGen RandomKeyGenerator, api huma.API) { // Routes have access to pool } // Store in context for handler access ctx = context.WithValue(ctx, PoolKey, pool)3. Interface-Based Testing# Use interfaces for testability:
// Production: Real random key generator type StandardKeyGen struct{} func (s StandardKeyGen) RandomKey(len int) (string, error) { b := make([]byte, len) _, err := rand.Read(b) return hex.EncodeToString(b), err } // Testing: Deterministic key generator type MockKeyGen struct { Keys []string idx int } func (m *MockKeyGen) RandomKey(len int) (string, error) { key := m.Keys[m.idx] m.idx++ return key, nil }4. Validation at Multiple Layers# // 1. Huma validates request structure type CreateEmbeddingInput struct { Body models.Embedding `maxLength:&#34;1000000&#34;` } // 2. Model validates business rules func (e *Embedding) Validate() error { if e.TextID == &#34;&#34; { return fmt.Errorf(&#34;text_id required&#34;) } return nil } // 3. Handler validates against database state func CreateEmbedding(ctx context.Context, input *CreateEmbeddingInput) error { // Check project exists // Validate dimensions match LLM service // Validate metadata against schema // Then insert }5. Error Wrapping# Provide context while preserving original error:
user, err := db.GetUserByHandle(ctx, handle) if err != nil { if errors.Is(err, pgx.ErrNoRows) { return nil, huma.Error404NotFound(&#34;user not found&#34;) } return nil, fmt.Errorf(&#34;failed to retrieve user %s: %w&#34;, handle, err) }Internal Packages# Go&rsquo;s internal/ directory enforces package privacy:
// This import works within dhamps-vdb import &#34;github.com/mpilhlt/dhamps-vdb/internal/database&#34; // This import would FAIL from external projects // Enforced by Go compilerBenefits:
Clear API boundaries Implementation details hidden Refactoring without breaking external users Performance Considerations# Connection Pooling# config.MaxConns = 20 // Max concurrent connections config.MinConns = 5 // Keep-alive connections config.MaxConnIdleTime = 5 * time.MinuteQuery Optimization# Use UNION ALL for better performance:
// Instead of LEFT JOIN with OR conditions query := ` SELECT * FROM projects WHERE owner = $1 UNION ALL SELECT p.* FROM projects p INNER JOIN projects_shared_with ps USING (project_id) WHERE ps.user_handle = $1 ORDER BY owner, project_handle `Index Strategy# -- Dimension filtering (very important) CREATE INDEX ON embeddings(project_id, vector_dim); -- Vector similarity (HNSW for accuracy) CREATE INDEX ON embeddings USING hnsw (vector vector_cosine_ops); -- Access lookups CREATE INDEX ON projects_shared_with(user_handle); CREATE INDEX ON projects(owner, project_handle);See Performance Guide for detailed optimization strategies.
Testing Architecture# Test Organization# // handlers_test.go - Setup and utilities func setupTestDB(t *testing.T) *pgxpool.Pool { } func createTestUser(t *testing.T, pool *pgxpool.Pool) *models.User { } // users_test.go - User-specific tests func TestCreateUser(t *testing.T) { } func TestGetUser(t *testing.T) { } // projects_sharing_test.go - Sharing feature tests func TestShareProject(t *testing.T) { }Testcontainers Integration# func setupTestDB(t *testing.T) *pgxpool.Pool { ctx := context.Background() // Start PostgreSQL with pgvector req := testcontainers.ContainerRequest{ Image: &#34;pgvector/pgvector:0.7.4-pg16&#34;, ExposedPorts: []string{&#34;5432/tcp&#34;}, Env: map[string]string{ &#34;POSTGRES_PASSWORD&#34;: &#34;password&#34;, &#34;POSTGRES_DB&#34;: &#34;testdb&#34;, }, } container, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{ ContainerRequest: req, Started: true, }) require.NoError(t, err) // Connect and migrate pool := connectAndMigrate(ctx, container) return pool }See Testing Guide for comprehensive testing documentation.
Build and Deployment# Building# # Development build go build -o dhamps-vdb main.go # Production build with optimizations go build -ldflags=&#34;-s -w&#34; -o dhamps-vdb main.go # Cross-compilation GOOS=linux GOARCH=amd64 go build -o dhamps-vdb-linux main.goDocker Build# Multi-stage build for minimal image:
# Build stage FROM golang:1.21-alpine AS builder WORKDIR /app COPY go.mod go.sum ./ RUN go mod download COPY . . RUN go build -ldflags=&#34;-s -w&#34; -o dhamps-vdb main.go # Runtime stage FROM alpine:latest RUN apk --no-cache add ca-certificates WORKDIR /root/ COPY --from=builder /app/dhamps-vdb . EXPOSE 8880 CMD [&#34;./dhamps-vdb&#34;]Configuration# Application reads configuration from:
Command line flags: --port 8080 Environment variables: SERVICE_PORT=8080 .env file: SERVICE_PORT=8080 Priority: CLI flags &gt; Environment &gt; .env file &gt; Defaults
